#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

ACTION="${1:-}"
case "$ACTION" in
  up) TOTAL_STAGES=6 ;;
  down) TOTAL_STAGES=2 ;;
  *)
    printf 'Usage: %s {up|down}\n' "${0##*/}" >&2
    exit 2
    ;;
esac

banner "Finance Assistant demo runtime $ACTION"

REPOSITORY="hankgalt/ai_finance_assitant"
PROJECT_ID="comfforts-369117"
REGION="us-west1"
BOOTSTRAP_BUCKET="${PROJECT_ID}-aifa-tf-bootstrap"
STAGING_BUCKET="${PROJECT_ID}-aifa-tf-staging"
SOURCE_INSTANCE="aifa-staging-postgres"
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
BOOTSTRAP_ROOT="$REPO_ROOT/infrastructure/terraform/bootstrap"
SHARED_ROOT="$REPO_ROOT/infrastructure/terraform/shared"
STAGING_ROOT="$REPO_ROOT/infrastructure/terraform/environments/staging"

# ── Stage 1: local identity and tool preflight ─────────────────────────────
stage "Verify local identity and tools"
say "This stage performs read-only checks and accepts no credential payload."
for tool in gcloud terraform git jq; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not available on PATH"; exit 1; }
done
if [[ "$ACTION" == "up" ]]; then
  command -v gh >/dev/null 2>&1 || { warn "gh is not available on PATH"; exit 1; }
fi
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
ACTIVE_PROJECT=$(gcloud config get-value project 2>/dev/null)
[[ "$ACTIVE_ACCOUNT" == "vtalwar.w@comfforts.com" ]] || { warn "unexpected active account: $ACTIVE_ACCOUNT"; exit 1; }
[[ "$ACTIVE_PROJECT" == "$PROJECT_ID" ]] || { warn "unexpected active project: $ACTIVE_PROJECT"; exit 1; }
CURRENT_BRANCH=$(git branch --show-current)
[[ "$CURRENT_BRANCH" == "main" ]] || { warn "switch to main before managing the demo runtime"; exit 1; }
[[ -z "$(git status --porcelain)" ]] || { warn "the repository has uncommitted changes"; exit 1; }
git rev-parse origin/main >/dev/null 2>&1 || { warn "origin/main is unavailable; fetch before continuing"; exit 1; }
[[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/main)" ]] || {
  warn "local main does not match the fetched origin/main"
  exit 1
}
if [[ "$ACTION" == "up" ]]; then
  gh auth status >/dev/null
  export TF_VAR_database_tier="db-g1-small"
fi
BACKEND_IMAGE="${TF_VAR_backend_image:-${GCP_BACKEND_IMAGE:-}}"
if [[ -z "$BACKEND_IMAGE" ]]; then
  ask BACKEND_IMAGE "Artifact Registry backend image pinned by @sha256:"
fi
[[ "$BACKEND_IMAGE" == us-west1-docker.pkg.dev/comfforts-369117/aifa-containers/*@sha256:* ]] || {
  warn "backend image must use the approved Artifact Registry and an immutable sha256 digest"
  exit 1
}
export TF_VAR_backend_image="$BACKEND_IMAGE"
terraform version
say "Verified $ACTIVE_ACCOUNT on $PROJECT_ID."

if [[ "$ACTION" == "down" ]]; then
  pause "Continue to the staging-only destroy-plan review?"

  # ── Stage 2: reviewed staging runtime destruction ───────────────────────
  stage "Review and destroy the demo runtime"
  say "Bootstrap state, shared Artifact Registry, WIF, budget, and the Qdrant cluster are outside this staging state."
  warn "All deployed Sessions, Portfolios, Goals, Runs, History, and Inspector data will be permanently deleted."
  warn "This also deletes staging service identities, jobs, networking, and regional Secret Manager payloads."
  warn "Backup/PITR recovery is not part of the private-demo MVP."
  terraform -chdir="$STAGING_ROOT" init -reconfigure \
    -backend-config="bucket=$STAGING_BUCKET" \
    -backend-config="prefix=foundation"
  if [[ -z "$(terraform -chdir="$STAGING_ROOT" state list)" ]]; then
    say "The staging runtime state is already empty; nothing needs to be destroyed."
    finish
    return
  fi
  if CURRENT_DATABASE_TIER=$(gcloud sql instances describe "$SOURCE_INSTANCE" \
    --project="$PROJECT_ID" \
    --format='value(settings.tier)' 2>/dev/null); then
    [[ -n "$CURRENT_DATABASE_TIER" ]] || { warn "could not resolve the current database tier"; exit 1; }
    SQL_GUARDS_ACTIVE=$(jq -r '
      [
        .settings.deletionProtectionEnabled,
        .settings.backupConfiguration.enabled,
        .settings.backupConfiguration.pointInTimeRecoveryEnabled,
        .settings.retainBackupsOnDelete,
        .settings.finalBackupConfig.enabled
      ] | any(. == true)
    ' < <(gcloud sql instances describe "$SOURCE_INSTANCE" \
      --project="$PROJECT_ID" \
      --format=json))
  else
    CURRENT_DATABASE_TIER="db-g1-small"
    SQL_GUARDS_ACTIVE="false"
    warn "the source Cloud SQL instance is already absent; evaluating only the remaining state"
  fi
  export TF_VAR_database_tier="$CURRENT_DATABASE_TIER"
  LIFECYCLE_PLAN=$(mktemp "${TMPDIR:-/tmp}/aifa-demo-lifecycle.XXXXXX")
  DESTROY_PLAN=$(mktemp "${TMPDIR:-/tmp}/aifa-demo-destroy.XXXXXX")
  trap 'rm -f "$LIFECYCLE_PLAN" "$DESTROY_PLAN"' EXIT
  terraform -chdir="$STAGING_ROOT" plan -lock-timeout=5m -out="$LIFECYCLE_PLAN"
  terraform -chdir="$STAGING_ROOT" show -no-color "$LIFECYCLE_PLAN"
  HAS_CREATE_OR_DELETE=$(terraform -chdir="$STAGING_ROOT" show -json "$LIFECYCLE_PLAN" |
    jq -r '[.resource_changes[]?.change.actions[]?] | any(. == "create" or . == "delete")')
  if [[ "$HAS_CREATE_OR_DELETE" == "true" ]]; then
    if [[ "$SQL_GUARDS_ACTIVE" == "true" ]]; then
      warn "the transition plan contains create/delete actions while Cloud SQL deletion guards remain active"
      warn "stop and reconcile the partial state before destroying the runtime"
      exit 1
    fi
    warn "the transition plan contains create/delete actions from a partial teardown"
    say "Skipping the transition apply so deleted resources are not recreated."
  else
    confirm "Apply only this reviewed transition plan to remove runtime deletion guards?" || exit 1
    terraform -chdir="$STAGING_ROOT" apply "$LIFECYCLE_PLAN"
  fi
  terraform -chdir="$STAGING_ROOT" plan -destroy -lock-timeout=5m -out="$DESTROY_PLAN"
  terraform -chdir="$STAGING_ROOT" show -no-color "$DESTROY_PLAN"
  DESTROY_CONFIRMATION="DESTROY EMPTY-DEMO-RUNTIME"
  say "Type exactly: $DESTROY_CONFIRMATION"
  printf '  > '
  read -r confirmation
  [[ "$confirmation" == "$DESTROY_CONFIRMATION" ]] || {
    warn "confirmation did not match; nothing was destroyed"
    exit 1
  }
  terraform -chdir="$STAGING_ROOT" apply "$DESTROY_PLAN"
  say "The demo runtime is absent; the reproducibility foundation remains."
  finish
  return
fi

pause "Continue to the remote-state bootstrap?"

# ── Stage 2: bootstrap remote state ────────────────────────────────────────
stage "Bootstrap protected Terraform state"
say "The first bucket is created once with gcloud, then immediately imported under Terraform ownership."
if ! gcloud storage buckets describe "gs://$BOOTSTRAP_BUCKET" >/dev/null 2>&1; then
  confirm "Create gs://$BOOTSTRAP_BUCKET with versioning, soft delete, and public-access prevention?" || exit 1
  gcloud storage buckets create "gs://$BOOTSTRAP_BUCKET" \
    --project="$PROJECT_ID" \
    --location="${REGION^^}" \
    --uniform-bucket-level-access \
    --public-access-prevention \
    --soft-delete-duration=7d
  gcloud storage buckets update "gs://$BOOTSTRAP_BUCKET" --versioning
fi
terraform -chdir="$BOOTSTRAP_ROOT" init -reconfigure \
  -backend-config="bucket=$BOOTSTRAP_BUCKET" \
  -backend-config="prefix=bootstrap"
if ! terraform -chdir="$BOOTSTRAP_ROOT" state show 'google_storage_bucket.terraform_state["bootstrap"]' >/dev/null 2>&1; then
  terraform -chdir="$BOOTSTRAP_ROOT" import \
    'google_storage_bucket.terraform_state["bootstrap"]' "$BOOTSTRAP_BUCKET"
fi
terraform -chdir="$BOOTSTRAP_ROOT" plan -lock-timeout=5m -out=bootstrap.tfplan
confirm "Apply only the reviewed state-bucket plan shown above?" || exit 1
terraform -chdir="$BOOTSTRAP_ROOT" apply bootstrap.tfplan

# ── Stage 3: shared delivery foundation ───────────────────────────────────
stage "Apply shared APIs, budget, registry, and WIF"
BILLING_ACCOUNT_NAME=$(gcloud billing projects describe "$PROJECT_ID" --format='value(billingAccountName)')
BILLING_ACCOUNT_ID="${BILLING_ACCOUNT_NAME##*/}"
terraform -chdir="$SHARED_ROOT" init -reconfigure \
  -backend-config="bucket=$BOOTSTRAP_BUCKET" \
  -backend-config="prefix=shared"
terraform -chdir="$SHARED_ROOT" plan -lock-timeout=5m \
  -var="billing_account_id=$BILLING_ACCOUNT_ID" \
  -out=shared.tfplan
confirm "Apply the reviewed shared-foundation plan shown above?" || exit 1
terraform -chdir="$SHARED_ROOT" apply shared.tfplan

# ── Stage 4: staging managed-state foundation ─────────────────────────────
stage "Apply the staging managed-state foundation"
warn "This creates the approved billable, disposable single-zone db-g1-small Cloud SQL instance."
terraform -chdir="$STAGING_ROOT" init -reconfigure \
  -backend-config="bucket=$STAGING_BUCKET" \
  -backend-config="prefix=foundation"
terraform -chdir="$STAGING_ROOT" plan -lock-timeout=5m -out=staging.tfplan
confirm "Apply the reviewed staging plan, including Cloud SQL?" || exit 1
terraform -chdir="$STAGING_ROOT" apply staging.tfplan

# ── Stage 5: protected GitHub environments and non-secret variables ───────
stage "Activate protected GitHub environments"
say "GitHub receives only project, provider, and service-account identifiers."
ENVIRONMENT_PAYLOAD=$(mktemp)
printf '%s\n' '{"wait_timer":0,"prevent_self_review":false,"reviewers":[{"type":"User","id":2118128}],"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}' > "$ENVIRONMENT_PAYLOAD"
for environment in staging production; do
  gh api --method PUT "repos/$REPOSITORY/environments/$environment" --input "$ENVIRONMENT_PAYLOAD" >/dev/null
  if ! gh api "repos/$REPOSITORY/environments/$environment/deployment-branch-policies" \
    --jq '.branch_policies[].name' | grep -qx main; then
    gh api --method POST "repos/$REPOSITORY/environments/$environment/deployment-branch-policies" \
      -f name=main >/dev/null
  fi
done
rm -f "$ENVIRONMENT_PAYLOAD"

STAGING_PROVIDER=$(terraform -chdir="$SHARED_ROOT" output -raw staging_workload_identity_provider)
STAGING_SERVICE_ACCOUNT=$(terraform -chdir="$SHARED_ROOT" output -raw staging_deploy_service_account)
PRODUCTION_PROVIDER=$(terraform -chdir="$SHARED_ROOT" output -raw production_workload_identity_provider)
PRODUCTION_SERVICE_ACCOUNT=$(terraform -chdir="$SHARED_ROOT" output -raw production_deploy_service_account)

for environment in staging production; do
  gh variable set GCP_PROJECT_ID --repo "$REPOSITORY" --env "$environment" --body "$PROJECT_ID"
done
gh variable set GCP_WORKLOAD_IDENTITY_PROVIDER --repo "$REPOSITORY" --env staging --body "$STAGING_PROVIDER"
gh variable set GCP_DEPLOY_SERVICE_ACCOUNT --repo "$REPOSITORY" --env staging --body "$STAGING_SERVICE_ACCOUNT"
gh variable set GCP_WORKLOAD_IDENTITY_PROVIDER --repo "$REPOSITORY" --env production --body "$PRODUCTION_PROVIDER"
gh variable set GCP_DEPLOY_SERVICE_ACCOUNT --repo "$REPOSITORY" --env production --body "$PRODUCTION_SERVICE_ACCOUNT"
say "Protected environments and non-secret identity variables are configured."

# ── Stage 6: short-lived identity smoke ───────────────────────────────────
stage "Run short-lived cloud identity smoke"
say "Both environments execute only gcloud projects describe through GitHub OIDC."
confirm "Dispatch the staging and production identity-smoke workflows from main?" || exit 1
gh workflow run cloud-identity-smoke.yml --repo "$REPOSITORY" --ref main -f environment=staging
gh workflow run cloud-identity-smoke.yml --repo "$REPOSITORY" --ref main -f environment=production
open_url "https://github.com/$REPOSITORY/actions/workflows/cloud-identity-smoke.yml"
step "Wait for both protected-environment runs to complete successfully."
pause "Press Enter after both runs pass, or Ctrl-C to stop and investigate."

finish
}

run_wizard "$@"; exit
